function mapMetrics(){return{viewportWidth:E.harborViewport.clientWidth,viewportHeight:E.harborViewport.clientHeight,worldWidth:MANILA_BOARD_WIDTH,worldHeight:MANILA_BOARD_HEIGHT}}
